import sys; sys.path.insert(0, 'python')
import asyncio
from synapse.autonomy import AutonomousDriver, RenderPlanner, PreFlightValidator, RenderEvaluator

# Mock handler interface
class MockHandler:
    async def call(self, tool_name, params):
        if tool_name == 'get_stage_info':
            return {'cameras': ['/cameras/cam1'], 'prim_count': 10, 'renderable_prims': 5}
        if tool_name == 'render_settings':
            return {'pixel_samples': 64, 'resolution_x': 1920, 'output_path': '/tmp/render/'}
        if tool_name == 'get_scene_info':
            return {'frame_start': 1, 'frame_end': 100}
        if tool_name == 'validate_frame':
            return {'valid': True}
        if tool_name == 'render_sequence':
            return {'frames': [{'frame': 1, 'output_path': '/tmp/1.exr'}], 'output_dir': '/tmp/'}
        return {}

async def main():
    handler = MockHandler()
    driver = AutonomousDriver(
        planner=RenderPlanner(),
        validator=PreFlightValidator(handler),
        evaluator=RenderEvaluator(),
        handler_interface=handler,
        max_iterations=2,
    )
    report = await driver.execute('render frame 1')
    print(f'Success: {report.success}')
    print(f'Iterations: {report.iterations}')
    print(f'Decisions: {len(report.decisions)}')
    for d in report.decisions:
        print(f'  [{d.context}] {d.decision}')
    print(f'Time: {report.total_time_seconds:.3f}s')

asyncio.run(main())
